package io.ochre.bridge;

import java.util.*;
import static io.ochre.bridge.ActionSupport.*;

/// Reads only GLFW's focused game-window input cache; never installs global keyboard hooks.
final class InputSnapshot {
 private InputSnapshot() { }
 static String name(int key) { if(key>=65&&key<=90||key>=48&&key<=57)return Character.toString((char)key);if(key>=290&&key<=314)return "F"+(key-289);return switch(key){case 32->"SPACE";case 256->"ESCAPE";case 257->"ENTER";case 258->"TAB";case 259->"BACKSPACE";case 260->"INSERT";case 261->"DELETE";case 262->"RIGHT";case 263->"LEFT";case 264->"DOWN";case 265->"UP";case 266->"PAGE_UP";case 267->"PAGE_DOWN";case 268->"HOME";case 269->"END";case 340->"LEFT_SHIFT";case 341->"LEFT_CONTROL";case 342->"LEFT_ALT";case 343->"LEFT_SUPER";case 344->"RIGHT_SHIFT";case 345->"RIGHT_CONTROL";case 346->"RIGHT_ALT";case 347->"RIGHT_SUPER";default->"KEY_"+key;}; }
 static boolean valid(int key){return key==32||key==39||key>=44&&key<=57||key==59||key==61||key>=65&&key<=93||key==96||key==161||key==162||key>=256&&key<=269||key>=280&&key<=284||key>=290&&key<=314||key>=320&&key<=336||key>=340&&key<=348;}
 static void read(Object client,Map<String,String> result)throws Exception{Object window=call(client,"getWindow");long handle=((Number)call(window,"handle")).longValue();Class<?> glfw=type(client,"org.lwjgl.glfw.GLFW");boolean focused=((Number)glfw.getMethod("glfwGetWindowAttrib",long.class,int.class).invoke(null,handle,0x00020001)).intValue()==1;result.put("focused",Boolean.toString(focused));Object mouseHandler=field(client,"mouseHandler");result.put("x",call(mouseHandler,"xpos").toString());result.put("y",call(mouseHandler,"ypos").toString());int count=0,mouse=0;if(focused){var key=glfw.getMethod("glfwGetKey",long.class,int.class);for(int code=32;code<=348;code++)if(valid(code)&&((Number)key.invoke(null,handle,code)).intValue()==1){result.put("key."+count+".code",Integer.toString(code));result.put("key."+count+++".name",name(code));}var button=glfw.getMethod("glfwGetMouseButton",long.class,int.class);for(int code=0;code<8;code++)if(((Number)button.invoke(null,handle,code)).intValue()==1)result.put("mouse."+mouse++,Integer.toString(code));}result.put("keys",Integer.toString(count));result.put("mouse_buttons",Integer.toString(mouse));}
 static void bindings(Object client,Map<String,String> result)throws Exception{Object options=field(client,"options");boolean gameplay=field(client,"player")!=null&&InputActions.screen(client)==null&&!(Boolean)call(client,"isPaused");for(var item:Map.of("forward","keyUp","backward","keyDown","left","keyLeft","right","keyRight","jump","keyJump","sneak","keyShift","sprint","keySprint","attack","keyAttack","use","keyUse").entrySet())result.put("input."+item.getKey(),Boolean.toString(gameplay&&(Boolean)call(field(options,item.getValue()),"isDown")));}
}
